    64	    public synchronized Reservation confirm(long reservationId) {
    65	        Reservation reservation = find(reservationId);
    66	        if (reservation.status() != ReservationStatus.PENDING) {
    67	            throw notAllowed(reservation, "confirm");
    68	        }
    69	        reservation.confirmPayment();
    70	        store.update(reservation);
    71	        Room room = roomOf(reservation);
    72	        ReservationReceipt receipt = new ReservationReceipt(reservation, room);
    73	        emailSender.send(
    74	                reservation.guest().email(),
    75	                "Reserva confirmada - " + HOTEL_NAME,
    76	                confirmationEmailBody(reservation, receipt));
    77	        notifications.onConfirmation(reservation, room);
    78	        return reservation;
    79	    }
