    82	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    83	     * reservation was never paid, so nothing comes back).
    84	     */
    85	    public synchronized Reservation cancel(long reservationId) {
    86	        Reservation reservation = find(reservationId);
    87	        if (reservation.status() != ReservationStatus.PENDING
    88	                && reservation.status() != ReservationStatus.CONFIRMED) {
    89	            throw notAllowed(reservation, "cancel");
    90	        }
    91	        boolean wasConfirmed = reservation.status() == ReservationStatus.CONFIRMED;
    92	        BigDecimal refund = switch (reservation.ratePlan()) {
    93	            case STANDARD -> reservation.amountPaid();
    94	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
    95	        };
    96	        reservation.cancel(refund);
    97	        store.update(reservation);
    98	        if (wasConfirmed) {
    99	            notifications.onCancellation(reservation, roomOf(reservation));
   100	        }
   101	        return reservation;
   102	    }
   103	
   104	    public synchronized Reservation checkIn(long reservationId) {
   105	        Reservation reservation = find(reservationId);
   106	        if (reservation.status() != ReservationStatus.CONFIRMED) {
   107	            throw notAllowed(reservation, "check in");
   108	        }
   109	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   110	        store.update(reservation);
   111	        return reservation;
   112	    }
   113	
   114	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   115	    public synchronized ReservationReceipt checkOut(long reservationId) {
   116	        Reservation reservation = find(reservationId);
   117	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   118	            throw notAllowed(reservation, "check out");
   119	        }
   120	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   121	        store.update(reservation);
   122	        return new ReservationReceipt(reservation, roomOf(reservation));
   123	    }
   124	
   125	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   126	    public ReservationReceipt receiptCopy(long reservationId) {
   127	        Reservation reservation = find(reservationId);
   128	        if (!reservation.isPaid()) {
   129	            throw notAllowed(reservation, "issue a receipt for");
   130	        }
   131	        return new ReservationReceipt(reservation, roomOf(reservation));
   132	    }
   133	
   134	    private Room roomOf(Reservation reservation) {
   135	        return rooms.find(reservation.roomNumber()).orElseThrow();
   136	    }
   137	
   138	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   139	        return "Olá, " + reservation.guest().name() + "!\n\n"
   140	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   141	                + receipt.text() + "\n"
   142	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   143	                + "Até breve!\n";
   144	    }
   145	
   146	    private static HotelException notAllowed(Reservation reservation, String operation) {
   147	        return new HotelException(
   148	                ErrorCode.OPERATION_NOT_ALLOWED,
   149	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   150	    }
   151	}
